def run_agent(client, messages, tools):
    while True:
        response = client.complete(messages=messages, tools=list(tools))
        messages.append(response.message)
        if not response.tool_calls:
            return response.text
        for call in response.tool_calls:
            result = tools[call.name](**call.arguments)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})

from splunk_ao import log
def run_agent(client, messages, tools):
    while True:
        response = client.complete(messages=messages, tools=list(tools))
        messages.append(response.message)
        if not response.tool_calls:
            return response.text
        for call in response.tool_calls:
            result = tools[call.name](**call.arguments)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})

run_agent = log(run_agent)

func RunAgent(ctx context.Context, model Model, tools map[string]Tool, history []Message) (string, error) {
 for {
  reply, err := model.Complete(ctx, history, tools)
  if err != nil { return "", err }; history = append(history, reply.Message)
  if len(reply.Calls) == 0 { return reply.Text, nil }
  for _, call := range reply.Calls { value, err := tools[call.Name](ctx, call.Arguments); if err != nil { return "", err }; history = append(history, ToolResult(call.ID, value)) }
 }
}

