"""Probe public OTel creation facts; never execute or replace the AO SDK."""
import importlib.metadata
import json
from opentelemetry.trace import SpanKind
from opentelemetry.sdk.trace import TracerProvider, SpanProcessor
from opentelemetry.sdk.trace.sampling import Sampler, SamplingResult, Decision
from opentelemetry.sdk.trace.export import SimpleSpanProcessor
from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter

class SamplingProbe(Sampler):
    def __init__(self):
        self.seen = []
    def should_sample(self, parent_context, trace_id, name, kind=SpanKind.INTERNAL,
                      attributes=None, links=None, trace_state=None):
        self.seen.append({'name': name, 'kind': kind.name, 'attributes': dict(attributes or {})})
        return SamplingResult(Decision.RECORD_AND_SAMPLE, attributes=attributes)
    def get_description(self):
        return 'source-capability-probe'

class StartProbe(SpanProcessor):
    def __init__(self):
        self.seen = []
    def on_start(self, span, parent_context=None):
        self.seen.append({'name': span.name, 'kind': span.kind.name, 'attributes': dict(span.attributes or {})})
    def on_end(self, span):
        pass
    def shutdown(self):
        pass
    def force_flush(self, timeout_millis=30000):
        return True

sampler = SamplingProbe()
start = StartProbe()
exporter = InMemorySpanExporter()
provider = TracerProvider(sampler=sampler)
provider.add_span_processor(start)
provider.add_span_processor(SimpleSpanProcessor(exporter))
tracer = provider.get_tracer('public-creation-probe')
with tracer.start_as_current_span('name-only') as span:
    span.set_attribute('example.exit_field', True)
fields = {'gen_ai.operation.name': 'chat', 'gen_ai.request.model': 'synthetic-model'}
with tracer.start_as_current_span('explicit-client', kind=SpanKind.CLIENT, attributes=fields):
    pass
ended = [{'name': span.name, 'kind': span.kind.name, 'attributes': dict(span.attributes)}
         for span in exporter.get_finished_spans()]
assert sampler.seen[0] == start.seen[0] == {'name': 'name-only', 'kind': 'INTERNAL', 'attributes': {}}
assert ended[0]['attributes'] == {'example.exit_field': True}
assert sampler.seen[1]['kind'] == start.seen[1]['kind'] == ended[1]['kind'] == 'CLIENT'
assert sampler.seen[1]['attributes'] == start.seen[1]['attributes'] == ended[1]['attributes'] == fields
print(json.dumps({'sdk': importlib.metadata.version('opentelemetry-sdk'), 'sampling': sampler.seen,
                  'on_start': start.seen, 'ended': ended}, indent=2))
provider.shutdown()

